export const designDecks = Object.fromEntries(Object.entries(slideTitles).map(([topic, titles]) => {
  const directory = `assets/design/decks/${topic}`;
  const pdf = topic === '21' ? 'assets/design/multiplayer-maps/original-slides.pdf' : `${directory}/presentation.pdf`;
  const slides = titles.map((title, index) => ({
    title,
    thumbnail: `${directory}/${String(index + 1).padStart(2, '0')}.jpg`,
  }));
  return [topic, {pdf, slides}];
}));
